CREATE OR REPLACE FUNCTION public.set_family_member_color_for_current_user(target_member_id uuid, member_color text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_family_id uuid;
  target_family_id uuid;
  can_manage boolean;
begin
  if member_color not in ('red','yellow','blue','green','purple','orange','teal','pink') then
    raise exception 'Ogiltig familjefärg';
  end if;

  select family_id into current_family_id
  from public.family_members
  where user_id = auth.uid()
  order by created_at
  limit 1;

  if current_family_id is null then
    raise exception 'Ingen familj hittades';
  end if;

  select family_id into target_family_id
  from public.family_members
  where id = target_member_id;

  if target_family_id is distinct from current_family_id then
    raise exception 'Medlemmen tillhör inte din familj';
  end if;

  select coalesce(fp.can_manage_members, false) into can_manage
  from public.family_permissions fp
  join public.family_members fm on fm.id = fp.family_member_id
  where fm.user_id = auth.uid()
    and fm.family_id = current_family_id
  limit 1;

  if not can_manage and not exists (
    select 1 from public.family_members
    where id = target_member_id and user_id = auth.uid()
  ) then
    raise exception 'Du saknar behörighet att ändra färgen';
  end if;

  update public.family_members
  set color = member_color
  where id = target_member_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.normalize_meal_menu_created_by()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare resolved_user_id uuid;
begin
  if new.created_by is not null then
    select fm.user_id into resolved_user_id
    from public.family_members fm
    where fm.id = new.created_by
      and fm.user_id is not null
    limit 1;
    if resolved_user_id is not null then
      new.created_by := resolved_user_id;
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.reserve_wishlist_item(p_item_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.family_members; list public.family_wishlists;
begin
 select w.* into list from public.family_wishlists w join public.family_wishlist_items i on i.wishlist_id=w.id where i.id=p_item_id for update of w;
 select * into actor from public.family_members me where me.family_id=list.family_id and me.user_id=(select auth.uid()) and me.role<>'barn';
 if actor.id is null then raise exception 'Not permitted to reserve' using errcode='42501';end if;
 insert into public.family_wishlist_reservations(item_id,reserved_by)values(p_item_id,actor.id);
 exception when unique_violation then raise exception 'Already reserved';
end $function$

CREATE OR REPLACE FUNCTION public.notify_family_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  recipient uuid;
  actor uuid;
begin
  if tg_table_name = 'family_chat_messages' then
    if tg_op = 'INSERT' then
      insert into public.notifications (family_id, recipient_member_id, type, title, body, href, metadata)
      select new.family_id, fm.id, 'chat', 'Nytt meddelande', left(new.body, 120), '/chat', jsonb_build_object('message_id', new.id)
      from public.family_members fm
      where fm.family_id = new.family_id and fm.id <> new.member_id;
    end if;
    return new;
  end if;

  if tg_table_name = 'help_requests' then
    if tg_op = 'INSERT' then
      insert into public.notifications (family_id, recipient_member_id, type, title, body, href, metadata)
      select new.family_id, fm.id, 'help', 'Familjen behöver hjälp', new.title, '/hjalp', jsonb_build_object('help_request_id', new.id)
      from public.family_members fm
      where fm.family_id = new.family_id and fm.id <> new.created_by_member_id;
    elsif tg_op = 'UPDATE' and new.claimed_by_member_id is distinct from old.claimed_by_member_id and new.claimed_by_member_id is not null then
      insert into public.notifications (family_id, recipient_member_id, type, title, body, href, metadata)
      select new.family_id, member.id, 'help',
        coalesce((select nullif(helper.display_name, '') from public.family_members helper
          where helper.id = new.claimed_by_member_id and helper.family_id = new.family_id), 'En familjemedlem')
        || ' hjälper ' ||
        coalesce((select nullif(requester.display_name, '') from public.family_members requester
          where requester.id = new.created_by_member_id and requester.family_id = new.family_id), 'en familjemedlem'),
        new.title, '/hjalp',
        jsonb_build_object('help_request_id', new.id, 'claimed_by_member_id', new.claimed_by_member_id,
          'created_by_member_id', new.created_by_member_id, 'action', 'help_claimed')
      from public.family_members member
      where member.family_id = new.family_id;
    end if;
    return new;
  end if;

  if tg_table_name = 'family_tasks' then
    if tg_op = 'INSERT' and new.assigned_member_id is not null then
      insert into public.notifications (family_id, recipient_member_id, type, title, body, href, metadata)
      values (new.family_id, new.assigned_member_id, 'task', 'Ny uppgift', new.title, '/uppgifter', jsonb_build_object('task_id', new.id));
    elsif tg_op = 'UPDATE' and new.assigned_member_id is distinct from old.assigned_member_id and new.assigned_member_id is not null then
      insert into public.notifications (family_id, recipient_member_id, type, title, body, href, metadata)
      values (new.family_id, new.assigned_member_id, 'task', 'Ny uppgift till dig', new.title, '/uppgifter', jsonb_build_object('task_id', new.id));
    end if;
    return new;
  end if;

  if tg_table_name = 'calendar_events' then
    if new.responsible_member_id is not null and (tg_op = 'INSERT' or new.responsible_member_id is distinct from old.responsible_member_id) then
      insert into public.notifications (family_id, recipient_member_id, type, title, body, href, metadata)
      values (new.family_id, new.responsible_member_id, 'calendar', 'Du har fått ansvar', new.title, '/kalender', jsonb_build_object('event_id', new.id));
    end if;
    return new;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.unreserve_wishlist_item(p_item_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare list public.family_wishlists;
begin
 select w.* into list from public.family_wishlists w join public.family_wishlist_items i on i.wishlist_id=w.id where i.id=p_item_id for update of w;
 delete from public.family_wishlist_reservations r using public.family_members me where r.item_id=p_item_id and me.id=r.reserved_by and me.family_id=list.family_id and me.user_id=(select auth.uid()) and me.role<>'barn';
 if not found then raise exception 'Only your own reservation can be removed';end if;
end $function$

CREATE OR REPLACE FUNCTION public.create_family_invitation(p_member_id uuid, p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.family_members; target public.family_members; secret text; invitation_id uuid;
begin
 if auth.uid() is null then raise exception 'Logga in först.'; end if;
 select * into actor from public.family_members where user_id=auth.uid();
 if actor.id is null or actor.role<>'admin' then raise exception 'Bara Admin får bjuda in medlemmar.'; end if;
 perform 1 from public.families where id=actor.family_id for update;
 if not exists(select 1 from public.family_members where id=actor.id and user_id=auth.uid() and role='admin') then raise exception 'Bara Admin får hantera medlemmar.'; end if;
 select * into target from public.family_members where id=p_member_id and family_id=actor.family_id;
 if target.id is null or target.user_id is not null or target.role='barn' then raise exception 'Välj en vuxen familjeprofil utan kopplat konto. Barn får en barninloggning.'; end if;
 if length(btrim(p_email))>254 or btrim(p_email) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Ange en giltig e-postadress.'; end if;
 secret:=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-','');
 update public.family_invitations set revoked_at=now() where member_id=target.id and accepted_at is null and revoked_at is null;
 insert into public.family_invitations(family_id,member_id,email,token_hash,created_by)
 values(actor.family_id,target.id,lower(btrim(p_email)),encode(sha256(convert_to(secret,'UTF8')),'hex'),auth.uid()) returning id into invitation_id;
 return jsonb_build_object('id',invitation_id,'token',secret);
end;$function$

CREATE OR REPLACE FUNCTION public.revoke_family_invitation(p_invitation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.family_members;
begin
 select * into actor from public.family_members where user_id=auth.uid();
 if actor.id is null or actor.role<>'admin' then raise exception 'Bara Admin får återkalla inbjudningar.'; end if;
 perform 1 from public.families where id=actor.family_id for update;
 if not exists(select 1 from public.family_members where id=actor.id and user_id=auth.uid() and role='admin') then raise exception 'Bara Admin får hantera medlemmar.'; end if;
 update public.family_invitations set revoked_at=now() where id=p_invitation_id and family_id=actor.family_id and accepted_at is null;
 if not found then raise exception 'Inbjudningen kunde inte återkallas.'; end if;
end;$function$

CREATE OR REPLACE FUNCTION public.accept_family_invitation(p_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare invitation public.family_invitations; email_address text; confirmed timestamptz; child_account boolean;
begin
 if auth.uid() is null then raise exception 'Logga in för att acceptera inbjudningen.'; end if;
 if p_token !~ '^[a-f0-9]{64}$' then raise exception 'Inbjudningen är ogiltig.'; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0));
 select email,email_confirmed_at,coalesce((raw_app_meta_data->>'parent_managed_child')::boolean,false)
 into email_address,confirmed,child_account from auth.users where id=auth.uid();
 if confirmed is null or child_account then raise exception 'Använd ett bekräftat vuxenkonto.'; end if;
 select * into invitation from public.family_invitations where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex');
 if invitation.id is null or invitation.email<>lower(email_address) then raise exception 'Inbjudningen gäller en annan e-postadress eller är ogiltig.'; end if;
 perform 1 from public.families where id=invitation.family_id for update;
 select * into invitation from public.family_invitations where id=invitation.id for update;
 if invitation.accepted_by=auth.uid() then return invitation.family_id; end if;
 if invitation.accepted_at is not null or invitation.revoked_at is not null or invitation.expires_at<=now() then raise exception 'Inbjudningen har gått ut, återkallats eller redan använts.'; end if;
 if exists(select 1 from public.family_members where user_id=auth.uid()) then raise exception 'Ditt konto hör redan till en familj. Kontakta Admin.'; end if;
 update public.family_members set user_id=auth.uid() where id=invitation.member_id and family_id=invitation.family_id and user_id is null and role<>'barn';
 if not found then raise exception 'Familjeprofilen kan inte kopplas. Be Admin skapa en ny inbjudning.'; end if;
 update public.family_invitations set accepted_at=now(),accepted_by=auth.uid() where id=invitation.id;
 return invitation.family_id;
end;$function$

CREATE OR REPLACE FUNCTION public.set_family_member_role(p_member_id uuid, p_role text, p_family_role text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.family_members; target public.family_members;
begin
 select * into actor from public.family_members where user_id=auth.uid();
 if actor.id is null or actor.role<>'admin' then raise exception 'Bara Admin får ändra roller.'; end if;
 if p_role not in ('admin','förälder','barn','familj') or p_role is null then raise exception 'Ogiltig roll.'; end if;
 perform 1 from public.families where id=actor.family_id for update;
 if not exists(select 1 from public.family_members where id=actor.id and user_id=auth.uid() and role='admin') then raise exception 'Bara Admin får hantera medlemmar.'; end if;
 select * into target from public.family_members where id=p_member_id and family_id=actor.family_id;
 if target.id is null then raise exception 'Familjemedlemmen kunde inte hittas.'; end if;
 if exists(select 1 from public.family_child_logins where member_id=target.id) and p_role<>'barn' then raise exception 'Ett föräldrahanterat barnkonto måste behålla barnrollen.'; end if;
 if target.role='admin' and target.user_id is not null and p_role<>'admin' and not exists(select 1 from public.family_members where family_id=actor.family_id and role='admin' and user_id is not null and id<>target.id) then raise exception 'Familjen måste ha minst en Admin med kopplat konto.'; end if;
 update public.family_members set role=p_role,family_role=case when p_role='barn' then null else coalesce(nullif(p_family_role,''),target.family_role,case when p_role='familj' then 'annan_nara_familj' else null end) end where id=target.id;
 update public.family_permissions set can_manage_family=p_role='admin',can_manage_members=p_role='admin',
 can_manage_calendar=p_role in ('admin','förälder'),can_create_events=p_role in ('admin','förälder'),can_manage_tasks=p_role in ('admin','förälder'),can_manage_lists=p_role in ('admin','förälder'),can_manage_wishlists=p_role in ('admin','förälder'),can_use_chat=true,can_upload_photos=p_role in ('admin','förälder') where family_member_id=target.id;
 update public.family_invitations set revoked_at=now() where member_id=target.id and accepted_at is null and revoked_at is null;
end;$function$

CREATE OR REPLACE FUNCTION public.add_family_member_for_current_user(member_name text, member_role text, member_family_role text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_user_id uuid := auth.uid();
  current_family_id uuid;
  current_member_id uuid;
  new_member_id uuid;
  normalized_role text := lower(trim(member_role));
  normalized_family_role text := nullif(lower(trim(member_family_role)), '');
begin
  if current_user_id is null then
    raise exception 'Not authenticated';
  end if;

  if nullif(trim(member_name), '') is null then
    raise exception 'Member name is required';
  end if;

  if normalized_role not in ('admin', 'förälder', 'barn', 'familj') then
    raise exception 'Invalid member role';
  end if;

  if normalized_role = 'familj' and normalized_family_role is null then
    raise exception 'Family relationship is required';
  end if;

  if normalized_role = 'barn' then
    normalized_family_role := null;
  end if;

  select fm.id, fm.family_id
    into current_member_id, current_family_id
  from public.family_members fm
  where fm.user_id = current_user_id
  order by fm.created_at
  limit 1;

  if current_family_id is null then
    raise exception 'Family membership not found';
  end if;

  if not exists (
    select 1
    from public.family_permissions fp
    where fp.family_member_id = current_member_id
      and fp.can_manage_members = true
      and exists(select 1 from public.family_members actor where actor.id = current_member_id and actor.role = 'admin')
  ) then
    raise exception 'You do not have permission to manage members';
  end if;

  perform 1 from public.families where id=current_family_id for update;
  if not exists(select 1 from public.family_members where id=current_member_id and user_id=auth.uid() and role='admin') then raise exception 'Bara Admin får hantera medlemmar.'; end if;

  insert into public.family_members (
    family_id,
    user_id,
    display_name,
    role,
    family_role
  )
  values (
    current_family_id,
    null,
    trim(member_name),
    normalized_role,
    normalized_family_role
  )
  returning id into new_member_id;

  insert into public.family_permissions (
    family_member_id,
    can_manage_family,
    can_manage_members,
    can_manage_calendar,
    can_create_events,
    can_manage_tasks,
    can_manage_lists,
    can_manage_wishlists,
    can_use_chat,
    can_upload_photos
  )
  values (
    new_member_id,
    normalized_role = 'admin',
    normalized_role = 'admin',
    normalized_role in ('admin', 'förälder'),
    normalized_role in ('admin', 'förälder'),
    normalized_role in ('admin', 'förälder'),
    normalized_role in ('admin', 'förälder'),
    normalized_role in ('admin', 'förälder'),
    true,
    false
  );

  return new_member_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_family_member_for_current_user(target_member_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_user_id uuid := auth.uid();
  current_member_id uuid;
  target_family_id uuid;
  target_role text;
  admin_count integer;
begin
  if current_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select fm.id, fm.family_id
    into current_member_id, target_family_id
  from public.family_members fm
  join public.family_permissions fp
    on fp.family_member_id = fm.id
  where fm.user_id = current_user_id
    and fp.can_manage_members = true
    and fm.role = 'admin'
  order by fm.created_at
  limit 1;

  if current_member_id is null then
    raise exception 'You do not have permission to manage family members';
  end if;

  perform 1 from public.families where id=target_family_id for update;
  if not exists(select 1 from public.family_members where id=current_member_id and user_id=auth.uid() and role='admin') then raise exception 'Bara Admin får hantera medlemmar.'; end if;

  if target_member_id = current_member_id then
    raise exception 'You cannot remove yourself from the family';
  end if;

  select fm.role
    into target_role
  from public.family_members fm
  where fm.id = target_member_id
    and fm.family_id = target_family_id;

  if target_role is null then
    raise exception 'Family member not found';
  end if;

  if target_role = 'admin' then
    select count(*)
      into admin_count
    from public.family_members fm
    where fm.family_id = target_family_id
      and fm.role = 'admin';

    if admin_count <= 1 then
      raise exception 'The last family admin cannot be removed';
    end if;
  end if;

  delete from public.family_wishlist_reservations where reserved_by=target_member_id;

  delete from public.family_members
  where id = target_member_id
    and family_id = target_family_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_family_for_current_user(family_name text, member_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  new_family_id uuid;
  current_user_id uuid := auth.uid();
begin
  if current_user_id is null then
    raise exception 'Not authenticated';
  end if;

  if nullif(trim(family_name), '') is null then
    raise exception 'Family name is required';
  end if;

  if nullif(trim(member_name), '') is null then
    raise exception 'Member name is required';
  end if;

  if exists(select 1 from auth.users where id=current_user_id and raw_app_meta_data @> '{"parent_managed_child":true}'::jsonb) then
    raise exception 'Barnkontot måste vara kopplat av en förälder och kan inte skapa en egen familj.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(current_user_id::text,0));

  if exists (
    select 1
    from public.family_members
    where user_id = current_user_id
  ) then
    select family_id
      into new_family_id
    from public.family_members
    where user_id = current_user_id
    order by created_at
    limit 1;

    return new_family_id;
  end if;

  insert into public.families (name)
  values (trim(family_name))
  returning id into new_family_id;

  insert into public.family_members (
    family_id,
    user_id,
    display_name,
    role
  )
  values (
    new_family_id,
    current_user_id,
    trim(member_name),
    'admin'
  );

  insert into public.family_permissions (
    family_member_id,
    can_manage_family,
    can_manage_members,
    can_manage_calendar,
    can_create_events,
    can_manage_tasks,
    can_manage_lists,
    can_manage_wishlists,
    can_use_chat,
    can_upload_photos
  )
  select
    fm.id,
    true,
    true,
    true,
    true,
    true,
    true,
    true,
    true,
    true
  from public.family_members fm
  where fm.family_id = new_family_id
    and fm.user_id = current_user_id;

  return new_family_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.link_parent_managed_child(p_member_id uuid, p_child_user_id uuid, p_guardian_user_id uuid, p_parent_email text, p_username text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from public.family_members child
    join public.family_members guardian on guardian.family_id = child.family_id
    where child.id = p_member_id and child.role = 'barn' and child.user_id is null
    and guardian.user_id = p_guardian_user_id and guardian.role in ('admin','förälder')
  ) then raise exception 'Not permitted'; end if;
  -- Auth identity/email are verified by the Edge Function before this service-only RPC.
  if p_child_user_id = p_guardian_user_id or exists(select 1 from public.family_members where user_id = p_child_user_id)
    then raise exception 'Invalid child account'; end if;
  update public.family_members set user_id = p_child_user_id where id = p_member_id and role = 'barn' and user_id is null;
  if not found then raise exception 'Child already linked'; end if;
  insert into public.family_child_logins(member_id,child_user_id,guardian_user_id,parent_email,username)
  values(p_member_id,p_child_user_id,p_guardian_user_id,p_parent_email,p_username);
end;
$function$

CREATE OR REPLACE FUNCTION public.change_help_request(p_request_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.family_members; item public.help_requests; helper_name text; requester_name text; notification_title text;
begin
 if auth.uid() is null then raise exception 'Logga in för att ändra hjälpärendet.'; end if;
 select * into me from public.family_members where user_id=auth.uid();
 if me.id is null then raise exception 'Ditt konto behöver vara kopplat till en familj.'; end if;
 select * into item from public.help_requests where id=p_request_id and family_id=me.family_id for update;
 if item.id is null then raise exception 'Hjälpärendet finns inte kvar. Listan har uppdaterats.'; end if;
 select * into me from public.family_members where user_id=auth.uid() and family_id=item.family_id;
 if me.id is null then raise exception 'Du kan inte ändra det här hjälpärendet.'; end if;
 case p_action
 when 'claim' then
  if item.completed_at is not null then raise exception 'Hjälpen är redan klar.'; end if;
  if item.claimed_by_member_id=me.id then return to_jsonb(item); end if;
  if item.claimed_by_member_id is not null then raise exception 'Någon annan hann ta ärendet. Listan har uppdaterats.'; end if;
  if item.created_by_member_id=me.id then raise exception 'Du kan markera din egen förfrågan som klar istället.'; end if;
  update public.help_requests set claimed_by_member_id=me.id,claimed_at=clock_timestamp() where id=item.id returning * into item;
 when 'release' then
  if item.completed_at is not null then raise exception 'Öppna det klara ärendet igen först.'; end if;
  if item.claimed_by_member_id is null then raise exception 'Ärendet är redan ledigt.'; end if;
  if item.claimed_by_member_id<>me.id and me.role<>'admin' then raise exception 'Bara den som hjälper eller Admin kan lämna tillbaka ärendet.'; end if;
  update public.help_requests set claimed_by_member_id=null,claimed_at=null where id=item.id returning * into item;
  notification_title:='Hjälpärendet är ledigt igen';
 when 'complete' then
  if me.id<>item.created_by_member_id and me.id is distinct from item.claimed_by_member_id and me.role<>'admin' then raise exception 'Bara den som ber om hjälp, den som hjälper eller Admin kan markera klart.'; end if;
  if item.completed_at is not null then return to_jsonb(item); end if;
  update public.help_requests set completed_at=clock_timestamp() where id=item.id returning * into item;
  select display_name into helper_name from public.family_members where id=item.claimed_by_member_id and family_id=item.family_id;
  select display_name into requester_name from public.family_members where id=item.created_by_member_id and family_id=item.family_id;
  notification_title:=case when helper_name is null then 'Hjälpen är klar' else helper_name||' hjälpte '||coalesce(requester_name,'en familjemedlem') end;
 when 'reopen' then
  if me.id<>item.created_by_member_id and me.id is distinct from item.claimed_by_member_id and me.role<>'admin' then raise exception 'Bara de berörda eller Admin kan öppna ärendet igen.'; end if;
  if item.completed_at is null then return to_jsonb(item); end if;
  update public.help_requests set completed_at=null where id=item.id returning * into item;
  notification_title:='Hjälpärendet har öppnats igen';
 else raise exception 'Ogiltig ändring av hjälpärendet.';
 end case;
 if notification_title is not null then
  insert into public.notifications(family_id,recipient_member_id,type,title,body,href,metadata)
  select item.family_id,recipient.id,'help',notification_title,item.title,'/hjalp',jsonb_build_object('help_request_id',item.id,'action','help_'||p_action)
  from public.family_members recipient where recipient.family_id=item.family_id;
 end if;
 return to_jsonb(item);
end;$function$

CREATE OR REPLACE FUNCTION public.create_daily_tasks(p_title text, p_member_ids uuid[], p_xp integer, p_start date, p_end date, p_request_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare actor public.family_members; recipient uuid; series uuid; count_days integer; total integer:=0; existing integer;
begin
  select * into actor from public.family_members where user_id=(select auth.uid());
  if actor.id is null or actor.role='barn' then raise exception 'Dagliga uppgifter skapas av en vuxen.' using errcode='42501'; end if;
  if p_title is null or length(btrim(p_title)) not between 1 and 200 or p_xp is null or p_xp not between 0 and 10000
    or p_start is null or p_end is null or p_end-p_start not between 0 and 365 or p_request_id is null
    or p_start<(clock_timestamp() at time zone 'Europe/Stockholm')::date then raise exception 'Kontrollera titel, XP och datum (högst 366 dagar).'; end if;
  if p_member_ids is null or cardinality(p_member_ids) not between 1 and 30 or exists(
    select 1 from unnest(p_member_ids) child_id where child_id is null or not exists(
      select 1 from public.family_members where id=child_id and family_id=actor.family_id and role='barn')) then
    raise exception 'Välj barn i din familj.' using errcode='42501'; end if;
  count_days:=p_end-p_start+1;
  foreach recipient in array (select array_agg(distinct id) from unnest(p_member_ids) id) loop
    -- The same request and child always produce the same series, making retries safe.
    series:=md5(p_request_id::text||recipient::text)::uuid;
    insert into public.family_tasks(family_id,title,assigned_member_id,xp,due_at,created_by,scheduled_date,daily_series_id,series_start,series_end)
    select actor.family_id,btrim(p_title),recipient,p_xp,((p_start+n)::timestamp+interval '12 hours') at time zone 'Europe/Stockholm',
      actor.user_id,p_start+n,series,p_start,p_end from generate_series(0,count_days-1)n
    on conflict(daily_series_id,scheduled_date) where daily_series_id is not null do nothing;
    get diagnostics existing=row_count; total:=total+existing;
  end loop;
  return total;
end $function$

CREATE OR REPLACE FUNCTION public.save_budget_month(p_month date, p_action text, p_personal boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.family_members; snapshot_data jsonb; owner_id uuid;
begin
 select * into me from public.family_members where user_id=(select auth.uid()) and role in ('admin','förälder');
 if me.id is null then raise exception 'Budgeten är bara för föräldrar.' using errcode='42501';end if;
 if p_month is null or extract(day from p_month)<>1 or p_action not in ('save','reopen') or p_action is null or p_personal is null then raise exception 'Ogiltig månad eller åtgärd.';end if;
 owner_id:=case when p_personal then me.id else null end;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(me.family_id::text||p_month::text||coalesce(owner_id::text,''),0));
 if p_action='reopen' then update public.family_budget_months set saved_at=null where family_id=me.family_id and month=p_month and owner_member_id is not distinct from owner_id;return;end if;
 if exists(select 1 from public.family_budget_months where family_id=me.family_id and month=p_month and owner_member_id is not distinct from owner_id and saved_at is not null) then return;end if;
 select jsonb_build_object('entries',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'title',e.title,'kind',e.kind,'amount_cents',e.amount_cents,'member_id',e.member_id,'shared',e.shared) order by e.created_at,e.id) from public.family_budget_entries e where e.family_id=me.family_id and e.month=p_month and e.owner_member_id is not distinct from owner_id),'[]'::jsonb),
 'parents',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'display_name',p.display_name) order by p.created_at,p.id) from public.family_members p where p.family_id=me.family_id and p.role in ('admin','förälder') and (not p_personal or p.id=me.id)),'[]'::jsonb)) into snapshot_data;
 insert into public.family_budget_months(family_id,month,owner_member_id,saved_at,snapshot)values(me.family_id,p_month,owner_id,clock_timestamp(),snapshot_data)
 on conflict on constraint budget_month_scope do update set saved_at=excluded.saved_at,snapshot=excluded.snapshot;
end $function$

CREATE OR REPLACE FUNCTION public.import_registered_birthday()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare value text; parsed date;
begin
 if new.user_id is null then return new; end if;
 select raw_user_meta_data->>'birth_date' into value from auth.users where id=new.user_id;
 if value ~ '^\d{4}-\d{2}-\d{2}$' and pg_input_is_valid(value,'date') then
  parsed:=value::date;
  if parsed between date '1900-01-01' and (now() at time zone 'Europe/Stockholm')::date then
   insert into public.member_birthdays(member_id,birth_date) values(new.id,parsed) on conflict(member_id) do nothing;
  end if;
 end if;
 return new;
end;$function$
